  `recommendedMedicines` json DEFAULT NULL,
  `recommendedFoods` json DEFAULT NULL,
  `foodsToAvoid` json DEFAULT NULL,
  `recommendedYoga` json DEFAULT NULL,
  `recommendedExercises` json DEFAULT NULL,
  `dailyRoutine` text COLLATE utf8mb4_unicode_ci,
  `sleepRecommendation` text COLLATE utf8mb4_unicode_ci,
  `stressManagement` text COLLATE utf8mb4_unicode_ci,
