  `bodyPartsAffected` json DEFAULT NULL,
  `ageGroup` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `gender` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `pregnancySafe` tinyint(1) DEFAULT '1',
  `contagious` tinyint(1) DEFAULT '0',
  `severity` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
