INSERT INTO `diseases` (`id`, `diseaseName`, `slug`, `scientificName`, `alternativeNames`, `category`, `subCategory`, `overview`, `description`, `causes`, `symptoms`, `earlySymptoms`, `advancedSymptoms`, `riskFactors`, `complications`, `prevention`, `homeRemedies`, `ayurvedicTreatment`, `modernTreatment`, `recommendedHerbs`, `recommendedMedicines`, `recommendedFoods`, `foodsToAvoid`, `recommendedYoga`, `recommendedExercises`, `dailyRoutine`, `sleepRecommendation`, `stressManagement`, `doshaAffected`, `bodyPartsAffected`, `ageGroup`, `gender`, `pregnancySafe`, `contagious`, `severity`, `recoveryTime`, `consultDoctorWhen`, `emergencyWarning`, `successRate`, `FAQs`, `references`, `doctorSpecialization`, `relatedDiseases`, `featuredImage`, `galleryImages`, `videoLinks`, `rating`, `views`, `bookmarks`, `createdAt`, `updatedAt`) VALUES
  ('dis-1', 'Diabetes', 'diabetes', 'Diabetes mellitus', '[\"Madhumeha\",\"Prameha\"]', 'Lifestyle Diseases', 'Metabolic Disorders', 'A metabolic condition characterized by high blood glucose levels, understood in Ayurveda as Madhumeha, involving Kapha-Pitta dosha imbalances.', 'In Ayurveda, Diabetes is known as Madhumeha, which is a type of Prameha (urinary disorder). It occurs due to low digestive fire (Agni) leading to toxic waste (Ama) accumulation in fat and muscle tissues, blocking metabolic channels and aggravating Vata dosha.', '[\"Sedentary lifestyle (Aasya Sukham)\",\"Excessive sleep (Swapna Sukham)\",\"Excessive intake of dairy, sweets, and heavy foods\",\"Inherited genetic factors (Sahaja)\"]', '[\"Excessive thirst (Trishna)\",\"Frequent urination (Prabhoota Mootrata)\",\"Fatigue and exhaustion (Klama)\",\"Numbness in hands and feet\",\"Unexplained weight loss\"]', '[\"Dryness in mouth\",\"Sweet taste in mouth\",\"Increased sleepiness\"]', '[\"Slow-healing wounds\",\"Frequent infections\",\"Vision changes\"]', '[\"Obesity\",\"Family history\",\"Chronic stress\",\"Lack of exercise\"]', '[\"Neuropathy (Nerve damage)\",\"Nephropathy (Kidney damage)\",\"Retinopathy (Eye damage)\"]', '[\"Maintain active physical routine\",\"Follow Kapha-reducing diet\",\"Regular screening and stress management\"]', '[\"Fenugreek seed powder with warm water\",\"Fresh bitter gourd juice daily\"]', 'Panchakarma therapies, specifically Virechana (purging) and Basti (medicated enemas), combined with deep-cleansing herbs to restore tissue metabolism and Agni.', 'Insulin therapy, oral hypoglycemic drugs, diet modification, and cardiovascular risk monitoring.', '[\"Gurmar (Gymnema sylvestre)\",\"Haridra (Turmeric)\",\"Amalaki (Amla)\",\"Vijaysar\"]', '[\"Chandraprabha Vati\",\"Nisha-Amalaki Churna\",\"Vasant Kusumakar Ras\"]', '[\"Barley\",\"Bitter gourd\",\"Fenugreek seeds\",\"Roasted chickpeas\",\"Quinoa\",\"Leafy greens\"]', '[\"Refined sugar\",\"White rice\",\"Yoghurt and heavy dairy\",\"Cold beverages\",\"Processed carbohydrates\"]', '[\"Mandukasana (Frog pose)\",\"Paschimottanasana\",\"Surya Namaskar\"]', '[\"Brisk walking (45 mins daily)\",\"Light cycling\"]', 'Wake up before sunrise, drink warm water, practice yoga, and avoid daytime sleeping.', '7-8 hours of sleep at night; completely avoid daytime naps which aggravate Kapha.', 'Daily practice of Pranayama (Anulom Vilom) and meditation for 15-20 minutes.', '[\"Kapha\",\"Pitta\",\"Vata\"]', '[\"Systemic\",\"Pancreas\",\"Kidneys\",\"Nerves\"]', 'Adults', 'All', 0, 0, 'High', 'Varies by individual and management (Chronic condition)', 'If blood sugar exceeds target range, or if you experience unexplained foot sores or numbness.', 'Sudden confusion, extreme drowsiness, rapid breathing, or loss of consciousness (Ketoacidosis risk).', 85, '[{\"answer\":\"Type 1 Diabetes is an autoimmune condition with insulin deficiency. Ayurveda focuses on supportive care, improving insulin sensitivity, and preventing complications, but cannot cure it.\",\"question\":\"Can Ayurveda cure Type 1 Diabetes?\"},{\"answer\":\"Yes, under expert Vaidya guidance, it supports blood sugar control. Monitor glucose levels regularly to avoid hypoglycemia.\",\"question\":\"Is Nisha-Amalaki safe to take with Metformin?\"}]', '[\"Charaka Samhita Nidana Sthana\",\"Sushruta Samhita\",\"Modern Clinical Endocrinology Studies\"]', 'Metabolic Specialist', '[\"obesity\",\"hypertension\"]', 'https://images.unsplash.com/photo-1579684385127-1ef15d508118?w=500&q=80', '[\"https://images.unsplash.com/photo-1579684385127-1ef15d508118?w=500&q=80\"]', '[]', '4.80', 350, 90, '2026-10-02 07:04:36', '2026-10-02 07:04:36'),
  ('dis-10', 'Anxiety', 'anxiety', 'Generalized Anxiety Disorder', '[\"Chittodvega\",\"Manovaha Srotas Roga\"]', 'Mental Wellness', 'Psychological Imbalances', 'A state of persistent worry and nervousness, classified as Chittodvega in Ayurveda, caused by aggravated Vata in the mind.', 'In Ayurveda, Anxiety is called Chittodvega. It is a psychological condition caused by aggravated Prana Vayu (a subtype of Vata) in the mind channels (Manovaha Srotas). It destabilizes thoughts, reduces mental strength (Sattva), and causes restlessness and worry.', '[\"Excessive mental workload and lack of rest\",\"Irregular lifestyle and diet habits\",\"Consuming dry, cold, and stale food\",\"Traumatic or highly stressful life events\"]', '[\"Persistent racing thoughts\",\"Heart palpitations (Hridrava)\",\"Nervous tremors or shaking\",\"Restlessness and inability to relax\",\"Cold hands and feet\"]', '[\"Mild muscle tension\",\"Occasional worry\",\"Slight concentration difficulty\"]', '[\"Panic attacks\",\"Hyperventilation\",\"Social isolation\"]', '[\"Stressful environment\",\"Genetic history\",\"Chronic illnesses\",\"Stimulants abuse\"]', '[\"Clinical depression\",\"Chronic insomnia\",\"Digestive problems (IBS)\"]', '[\"Maintain a grounding daily routine\",\"Eat warm, nourishing foods\",\"Practice daily breathing exercises\"]', '[\"Drink warm chamomile or tulsi tea\",\"Massage temples with Brahmi oil\"]', 'Shirodhara and full-body oil massage (Abhyanga) to ground Vata, combined with Sattvavajaya Chikitsa (Ayurvedic psychotherapy) and brain-stabilizing herbs.', 'Cognitive Behavioral Therapy (CBT), selective serotonin reuptake inhibitors (SSRIs), and mindfulness-based stress reduction.', '[\"Ashwagandha\",\"Brahmi (Bacopa monnieri)\",\"Shankhpushpi\",\"Jatamansi\"]', '[\"Manasamitra Vatakam\",\"Saraswatarishta\",\"Brahmi Gritha\"]', '[\"Warm, sweet, and oily foods\",\"Cooked root vegetables\",\"Ghee\",\"Warm soups and stews\",\"Sweet fruits\"]', '[\"Raw salads and cold foods\",\"Dry snacks like chips and crackers\",\"Caffeine, energy drinks, and alcohol\"]', '[\"Vrikshasana (Tree pose for grounding)\",\"Nadi Shodhana Pranayama\",\"Balasana\"]', '[\"Gentle walking in nature\",\"Tai Chi\"]', 'Start the day with silent meditation, self-massage with warm sesame oil, eat warm meals, and maintain a fixed bedtime.', '7-8 hours of sleep; keep bedroom warm and quiet.', 'Daily breathing techniques (Pranayama) and grounding exercises in nature.', '[\"Vata\"]', '[\"Nervous System\",\"Brain\",\"Mind (Manovaha Srotas)\"]', 'All', 'All', 1, 0, 'Moderate', 'Varies by individual (typically 4-8 weeks for noticeable relief)', 'If anxiety causes panic attacks or interferes with daily work and relationships.', 'Severe chest pain mimicking a heart attack, accompanied by severe difficulty breathing.', 88, '[{\"answer\":\"Ashwagandha acts as a natural adaptogen that lowers cortisol levels, nourishes nervous tissues, and calms Vata dosha in the brain.\",\"question\":\"How does Ashwagandha calm anxiety?\"},{\"answer\":\"Yes, raw vegetables are cold, dry, and light, which increases Vata dosha. Cooked, warm, and oily foods are much more grounding for anxiety.\",\"question\":\"Should I avoid raw salads if I have anxiety?\"}]', '[\"Charaka Samhita Sharira Sthana\",\"Bhavaprakasha Samhita\",\"American Psychological Association Guidelines\"]', 'Psychologist', '[\"insomnia\",\"migraine\"]', 'https://images.unsplash.com/photo-1506126613408-eca07ce68773?w=500&q=80', '[\"https://images.unsplash.com/photo-1506126613408-eca07ce68773?w=500&q=80\"]', '[]', '4.90', 490, 115, '2026-10-02 07:04:36', '2026-10-02 07:04:36'),
  ('dis-11', 'Hypertension', 'hypertension', 'Essential Hypertension', '[\"Rakta Gata Vata\",\"Uchha Rakta Chapa\"]', 'Lifestyle Diseases', 'Cardiovascular Disorders', 'High blood pressure condition causing vascular strain, matching Rakta Gata Vata in Ayurveda, involving Vata-Pitta.', 'In Ayurveda, Hypertension is understood as Rakta Gata Vata, where aggravated Vata dosha enters the blood channels (Rakta Vaha Srotas), narrowing blood vessels and raising pressure. Pitta dosha often contributes by causing vascular heat and inflammation.', '[\"Excessive salt and spicy food intake\",\"Sedentary lifestyle and obesity\",\"Chronic mental stress and anger\",\"Smoking and alcohol consumption\"]', '[\"Dizziness or lightheadedness\",\"Frequent headaches at back of head\",\"Palpitations\",\"Shortness of breath on mild exertion\",\"Fatigue\"]', '[\"Mild morning headaches\",\"Irritability\",\"Occasional flushing\"]', '[\"Chest pain\",\"Visual changes\",\"Nosebleeds (Epistaxis)\"]', '[\"Aging\",\"Obesity\",\"High salt diet\",\"Family history\"]', '[\"Heart Attack\",\"Stroke\",\"Kidney Damage\",\"Aneurysm\"]', '[\"Reduce dietary sodium\",\"Practice meditation daily\",\"Maintain moderate body weight\"]', '[\"Drink garlic-infused water daily\",\"Consume fresh watermelon juice in morning\"]', 'Shirodhara to calm stress-induced vascular pressure, mild purgation (Virechana) to clear blood toxins, and heart-tonic herbs.', 'Beta-blockers, ACE inhibitors, diuretics, and lifestyle modifications.', '[\"Arjuna (Terminalia arjuna)\",\"Sarpagandha (Rauvolfia serpentina)\",\"Brahmi\",\"Garlic (Lashuna)\"]', '[\"Sarpagandha Vati\",\"Arjunarishta\",\"Prabhakar Vati\"]', '[\"Barley and oatmeal\",\"Pomegranate\",\"Bottle gourd\",\"Garlic\",\"Skimmed milk in moderation\"]', '[\"Pickles and processed cheese\",\"Fried foods\",\"Red meat\",\"Alcohol and caffeine\"]', '[\"Shavasana\",\"Anulom Vilom Pranayama\",\"Chandra Bhedana\"]', '[\"Brisk walking (30 mins daily)\",\"Light cycling\"]', 'Wake up early, drink warm water, avoid arguments, eat light dinners, and massage head with cooling Brahmi oil.', '7-8 hours of peaceful sleep; avoid sleeping on your stomach.', 'Mindfulness meditation and calming music therapy.', '[\"Vata\",\"Pitta\"]', '[\"Heart\",\"Blood Vessels\",\"Brain\"]', 'Adults', 'All', 0, 0, 'High', 'Varies by individual and management (Chronic condition)', 'If blood pressure consistently reads above 140/90 mmHg, or if you feel severe headache.', 'Severe chest pain, sudden headache with numbness/weakness on one side of body, or difficulty speaking.', 85, '[{\"answer\":\"Arjuna is rich in natural coenzyme Q10 and flavonoids. It strengthens the cardiac muscles, improves vascular blood flow, and helps maintain healthy blood pressure.\",\"question\":\"Why is Arjuna bark recommended for the heart?\"},{\"answer\":\"No, but it should be heavily restricted. Standard table salt increases water retention. Rock salt (Saindhava Lavana) is a better, Vata-balancing alternative in small quantities.\",\"question\":\"Is salt completely prohibited?\"}]', '[\"Sushruta Samhita Sutra Sthana\",\"Bhavaprakasha Nighantu\",\"American Heart Association Guidelines\"]', 'Cardiologist', '[\"obesity\",\"diabetes\"]', 'https://images.unsplash.com/photo-1579684385127-1ef15d508118?w=500&q=80', '[\"https://images.unsplash.com/photo-1579684385127-1ef15d508118?w=500&q=80\"]', '[]', '4.80', 380, 80, '2026-10-02 07:04:36', '2026-10-02 07:04:36'),
  ('dis-12', 'Irritable Bowel Syndrome', 'ibs', 'Irritable Bowel Syndrome', '[\"Grahani Roga\"]', 'Digestive Disorders', 'Gastrointestinal Imbalances', 'A digestive disorder causing abdominal pain, cramping, and alternating diarrhea and constipation, known as Grahani in Ayurveda.', 'In Ayurveda, IBS is classified as Grahani Roga. It represents a weakness in the digestive fire (Agni) and the duodenum/colon lining (Grahani). It is caused by Vata-Pitta imbalances in the gut, leading to poor assimilation of food and erratic bowel movements.', '[\"Eating before previous meal is digested\",\"High psychological stress and anxiety\",\"Consuming incompatible or heavy junk food\",\"Irregular eating times\"]', '[\"Abdominal pain and cramping\",\"Alternating constipation and diarrhea\",\"Mucus in stool\",\"Bloating and excessive gas (Aflatulence)\",\"Feeling of incomplete evacuation\"]', '[\"Frequent gas after meals\",\"Stool consistency changes\",\"Gurgling sounds in abdomen\"]', '[\"Dehydration\",\"Weight loss\",\"Chronic abdominal spasms\"]', '[\"Chronic mental stress\",\"History of gastrointestinal infections\",\"Food sensitivities\",\"Sedentary routine\"]', '[\"Malnutrition due to poor absorption\",\"Chronic hemorrhoids\",\"Severe anxiety regarding bowel movements\"]', '[\"Eat freshly cooked warm food\",\"Incorporate buttermilk in daily diet\",\"Maintain consistent eating schedule\"]', '[\"Drink freshly churned buttermilk with cumin and rock salt\",\"Drink ginger-mint warm tea\"]', 'Digestive fire stimulators (Deepana-Pachana herbs) to burn raw toxins (Ama), followed by Vata-pacifying medicated enemas and gut-healing buttermilk diets.', 'Dietary fiber supplements, antispasmodic medications, laxatives or antidiarrheals, and stress management.', '[\"Bilva (Aegle marmelos)\",\"Kutaj (Holarrhena antidysenterica)\",\"Ginger\",\"Cumin (Jeeraka)\"]', '[\"Kutajghan Vati\",\"Bilvadi Churna\",\"Chitrakadi Vati\"]', '[\"Buttermilk churned with roasted cumin\",\"Pomegranate\",\"Mashed rice with Ghee\",\"Cooked bottle gourd\",\"Warm water\"]', '[\"Raw vegetables and salads\",\"Gluten and heavy wheat products\",\"Carbonated drinks\",\"Deep fried foods\",\"Spicy pickles\"]', '[\"Pawanmuktasana\",\"Vajrasana (after meals)\",\"Dhanurasana\"]', '[\"Gentle walking\",\"Deep abdominal breathing\"]', 'Eat meals in a calm environment, chew food thoroughly, drink warm water, and avoid cold drafts on the abdomen.', '7-8 hours of sleep; avoid staying awake past 10 PM.', 'Mindfulness and relaxation techniques to calm the gut-brain axis.', '[\"Vata\",\"Pitta\"]', '[\"Small Intestine\",\"Colon\",\"Stomach\"]', 'All', 'All', 1, 0, 'Moderate', 'Varies by individual (typically 2-4 months for gut stabilization)', 'If you experience blood in stool, unexplained weight loss, or persistent night diarrhea.', 'Severe persistent abdominal pain, high fever, or severe dehydration from constant watery diarrhea.', 87, '[{\"answer\":\"Takra is astringent, sour, and easy to digest. It stimulates Agni, binds stool, and populates the gut with healthy microflora, healing Grahani lining.\",\"question\":\"Why is buttermilk (Takra) considered a medicine in IBS?\"},{\"answer\":\"Yes, Ayurveda links the colon directly with Vata dosha and the mind. Psychological anxiety excites Prana Vayu, which disturbs gut motility.\",\"question\":\"Can stress trigger my IBS?\"}]', '[\"Charaka Samhita Chikitsa Sthana (Grahani Chikitsa)\",\"Madhava Nidana\",\"American College of Gastroenterology IBS Guidelines\"]', 'Gastroenterologist', '[\"anxiety\",\"gastritis\"]', 'https://images.unsplash.com/photo-1519494026892-80bbd2d6fd0d?w=500&q=80', '[\"https://images.unsplash.com/photo-1519494026892-80bbd2d6fd0d?w=500&q=80\"]', '[]', '4.80', 410, 105, '2026-10-02 07:04:36', '2026-10-02 07:04:36'),
  ('dis-13', 'Eczema', 'eczema', 'Atopic Dermatitis', '[\"Vicharchika\",\"Rakta Kushtha\"]', 'Skin Disorders', 'Dermatological Imbalances', 'An inflammatory skin condition causing itchy, dry rashes, matching Vicharchika in Ayurveda, involving Kapha-Pitta.', 'In Ayurveda, Eczema is classified as Vicharchika. It is a skin disorder caused by Kapha and Pitta dosha imbalances that pollute the blood and skin tissues. This leads to dry, itchy skin eruptions with discharge or scaling.', '[\"Frequent intake of incompatible food combinations\",\"Excessive use of spicy, sour, and salty foods\",\"Exposure to chemical allergens or dry cold air\",\"Poor personal hygiene or excess sweating\"]', '[\"Intense skin itching (Kandu)\",\"Dry, red, and inflamed skin patches\",\"Small fluid-filled blisters (discharge)\",\"Thickening and scaling of affected skin (Lichenification)\"]', '[\"Mild skin dryness\",\"Itching during nighttime\",\"Slight redness\"]', '[\"Crusting and oozing skin sores\",\"Painful cracks that bleed\",\"Secondary bacterial infections\"]', '[\"Atopic history (asthma, hay fever)\",\"Dry, cold climates\",\"Use of chemical cosmetics/soaps\",\"High stress levels\"]', '[\"Cellulitis (skin infection)\",\"Chronic skin scarring\",\"Sleep loss due to itching\"]', '[\"Apply natural oils before bathing\",\"Wear breathable cotton clothing\",\"Avoid harsh synthetic soaps\"]', '[\"Apply organic coconut oil with neem leaves extract\",\"Bathe in lukewarm water with oatmeal\"]', 'Blood purification therapies (Rakta Mokshana), gentle purgation (Virechana), and applying cooling, anti-inflammatory herbal pastes (Lepa).', 'Topical corticosteroids, emollients, antihistamines, and calcineurin inhibitors.', '[\"Neem\",\"Manjistha\",\"Khadir\",\"Turmeric\"]', '[\"Gandhak Rasayan\",\"Mahamanjishthadi Kadha\",\"Neem Taila\"]', '[\"Bitter vegetables\",\"Mung dal soup\",\"Warm water\",\"Cucumber\",\"Oats\"]', '[\"Sour fruits and pickles\",\"Fermented foods and curd\",\"Sea food and incompatible mixes\",\"Refined white sugar\",\"Spicy red chillies\"]', '[\"Anulom Vilom Pranayama\",\"Shavasana\",\"Trikonasana\"]', '[\"Light stretching\",\"Yoga in a cool room\"]', 'Moisturize skin immediately after bathing with pure coconut oil, avoid scratchy fabrics, and stay hydrated.', '7-8 hours of sleep; keep bedroom cool to prevent night itching.', 'Daily relaxation techniques and meditation.', '[\"Pitta\",\"Kapha\"]', '[\"Skin\",\"Hands & Feet\",\"Flexor surfaces (elbows, knees)\"]', 'All', 'All', 1, 0, 'Moderate', 'Varies by individual (typically 4-12 weeks for relief)', 'If skin eruptions show signs of infection (pus, warmth, red streaks) or if itching prevents sleep.', 'Widespread, extremely painful red blistering accompanied by high fever.', 87, '[{\"answer\":\"Neem is bitter (Tikta) and cooling, which neutralizes Pitta heat, purifies blood, and acts as a natural antimicrobial to prevent secondary infections.\",\"question\":\"Why is Neem recommended for Eczema?\"},{\"answer\":\"No, hot water strips the skin of its natural lipid barrier, causing severe dryness and worsening the eczema itch-scratch cycle.\",\"question\":\"Is hot water bathing good for eczema?\"}]', '[\"Charaka Samhita Chikitsa Sthana\",\"Madhava Nidana\",\"National Eczema Association Guidelines\"]', 'Ayurveda Skin Specialist', '[\"asthma\"]', 'https://images.unsplash.com/photo-1629909613654-28e377c37b09?w=500&q=80', '[\"https://images.unsplash.com/photo-1629909613654-28e377c37b09?w=500&q=80\"]', '[]', '4.80', 390, 90, '2026-10-02 07:04:36', '2026-10-02 07:04:36'),
  ('dis-14', 'Hypothyroidism', 'hypothyroidism', 'Hypothyroidism', '[\"Galaganda\",\"Dhatu Agnimandya\"]', 'Lifestyle Diseases', 'Endocrine Disorders', 'Underactive thyroid gland slowing metabolism, understood in Ayurveda as Galaganda or tissue-level Agni weakness.', 'In Ayurveda, Hypothyroidism is analyzed as Galaganda or Dhatu Agnimandya (tissue-level slow metabolic fire). Aggravated Kapha and Vata doshas block the throat channels (Galaganda path), slowing down the thyroid gland\'s metabolic function and causing fluid retention.', '[\"Sedentary lifestyle and lack of physical movement\",\"Excessive consumption of cold, heavy, and sweet foods\",\"Chronic stress and suppression of emotions\",\"Poor iodine intake or autoimmune triggers\"]', '[\"Unexplained weight gain\",\"Chronic fatigue and lethargy\",\"Sensitivity to cold\",\"Dry skin and thinning hair\",\"Constipation\"]', '[\"Mild swelling around throat\",\"Frequent muscle aches\",\"Brittle nails\"]', '[\"Goiter (swollen thyroid)\",\"Slow heart rate (Bradycardia)\",\"Cognitive slowdown (brain fog)\"]', '[\"Sedentary daily routine\",\"Female gender (higher susceptibility)\",\"Family history of thyroid disorders\",\"High stress levels\"]', '[\"Goiter\",\"Heart problems\",\"Myxedema coma (extreme cases)\",\"Infertility\"]', '[\"Follow a Kapha-reducing spicy diet\",\"Incorporate active neck-stimulating exercises\",\"Avoid sleeping in day\"]', '[\"Drink coriander seeds water on empty stomach\",\"Incorporate dry ginger in cooking\"]', 'Deep-cleansing powder massages (Udvartana), nasal drops (Nasya) to clear head/throat channels, and herbs that stimulate liver and thyroid metabolism (Agni).', 'Daily synthetic thyroid hormone replacement (Levothyroxine) therapy.', '[\"Kanchnar (Bauhinia variegata)\",\"Guggulu\",\"Triphala\",\"Punarnava\"]', '[\"Kanchnar Guggulu\",\"Punarnavadi Mandoor\",\"Arogyavardhini Vati\"]', '[\"Coriander seed infusions\",\"Barley and oats\",\"Spicy lentils\",\"Fresh gourd vegetables\",\"Walnuts\"]', '[\"Soy products\",\"Cruciferous vegetables (cabbage, broccoli) raw\",\"Cold dairy and sweets\",\"Excessive white rice\",\"Processed fats\"]', '[\"Sarvangasana (Shoulder stand)\",\"Halasana\",\"Ustrasana (Camel pose)\"]', '[\"Neck rotations\",\"Brisk walking (45 mins daily)\"]', 'Drink warm water with honey in the morning, practice throat-stimulating yoga poses, and eat light warm meals.', '7 hours of night sleep; strictly avoid daytime sleeping which slows down metabolism.', 'Pranayama (Ujjayi breathing) and meditation for emotional balance.', '[\"Kapha\",\"Vata\"]', '[\"Thyroid Gland\",\"Throat\",\"Metabolism (Systemic)\"]', 'Adults', 'All', 0, 0, 'Moderate', 'Varies by individual (typically 3-6 months for hormone stabilization)', 'If thyroid levels (TSH) are found outside range, or if you feel a lump or swelling in the throat.', 'Extreme lethargy, confusion, hypothermia, or swelling of the face and tongue.', 85, '[{\"answer\":\"Kanchnar bark has specific swelling-reducing (Gandamala-nashak) qualities. Combined with Guggulu, it clears channel blockages (Srotoshodhana) in the throat.\",\"question\":\"Why is Kanchnar Guggulu recommended for thyroid?\"},{\"answer\":\"Coriander seeds (Dhania) are rich in minerals and help stimulate thyroid gland pathways while improving overall digestive Agni.\",\"question\":\"Why coriander water is recommended?\"}]', '[\"Sushruta Samhita Chikitsa Sthana\",\"Bhavaprakasha Samhita\",\"American Thyroid Association Guidelines\"]', 'Endocrinologist', '[\"obesity\",\"insomnia\"]', 'https://images.unsplash.com/photo-1512428559087-560fa5ceab42?w=500&q=80', '[\"https://images.unsplash.com/photo-1512428559087-560fa5ceab42?w=500&q=80\"]', '[]', '4.70', 420, 100, '2026-10-02 07:04:36', '2026-10-02 07:04:36'),
  ('dis-15', 'Acne', 'acne', 'Acne vulgaris', '[\"Yuvana Pidika\",\"Mukhadushika\"]', 'Skin Disorders', 'Dermatological Imbalances', 'A skin condition causing pimples and blackheads, classified as Yuvana Pidika in Ayurveda, involving Pitta-Rakta.', 'In Ayurveda, Acne is known as Yuvana Pidika (youth eruptions) or Mukhadushika. It is caused by an aggravation of Pitta and Kapha doshas, which pollute the blood (Rakta) and clog the facial skin pores, leading to local inflammatory pustules.', '[\"High intake of spicy, oily, and junk foods\",\"Hormonal shifts during puberty/menstruation\",\"Improper facial hygiene and chemical cosmetics\",\"Digestive constipation\"]', '[\"Pimples and blackheads on face, back, chest\",\"Pus-filled eruptions (Pustules)\",\"Painful reddish skin nodules\",\"Oily facial skin\"]', '[\"Oily forehead and nose (T-zone)\",\"Small skin bumps\"]', '[\"Deep cystic acne\",\"Severe facial skin scarring\",\"Hyperpigmentation\"]', '[\"Adolescence\",\"Pitta-heavy constitution\",\"High stress levels\",\"Poor digestion\"]', '[\"Facial scarring (pits)\",\"Lower self-esteem and social anxiety\"]', '[\"Wash face twice daily with neem water\",\"Drink plenty of water\",\"Follow a Pitta-soothing diet\"]', '[\"Apply paste of sandalwood and turmeric topically\",\"Apply fresh aloe vera gel on pimples\"]', 'Blood purifying herbs, mild laxatives to clear bowel heat, and local applications of herbal face packs (Lepa) like Lodhra and Coriander.', 'Topical retinoids, benzoyl peroxide, oral antibiotics, and isotretinoin for severe cystic acne.', '[\"Neem\",\"Haridra (Turmeric)\",\"Lodhra\",\"Manjistha\"]', '[\"Kaishore Guggulu\",\"Raktashodhaka Bati\",\"Khadirarishta\"]', '[\"Bitter gourd and squash\",\"Fresh cucumber juice\",\"Mung dal\",\"Sweet fruits like apples\",\"Oats\"]', '[\"Spicy foods and green chillies\",\"Fermented foods and pickles\",\"Oily fried snacks\",\"Chocolates and carbonated drinks\",\"Excessive salt\"]', '[\"Pranayama (Sheetali)\",\"Sarvangasana\",\"Halasana\"]', '[\"Moderate exercise (wash face immediately after sweating)\"]', 'Keep facial skin clean, avoid popping pimples, drink warm water on waking, and ensure regular bowel clearance.', '7-8 hours of sleep; avoid sleeping on dirty pillowcases.', 'Calming yoga and breathing techniques.', '[\"Pitta\",\"Kapha\"]', '[\"Face\",\"Skin\",\"Blood (Rakta)\"]', 'Children', 'All', 1, 0, 'Low', 'Varies by individual (typically 2-6 weeks with natural treatment)', 'If acne becomes deeply painful, cystic, or leaves permanent pits/scars.', 'Sudden severe swelling of the face accompanied by high fever (indicative of acute skin infection).', 91, '[{\"answer\":\"Constipation causes body toxins (Ama) and heat (Pitta) to remain in the colon and re-enter the blood stream, manifesting as skin eruptions.\",\"question\":\"Why does constipation trigger acne?\"},{\"answer\":\"Yes, turmeric is anti-inflammatory and antiseptic. However, sensitive skin should mix it with cooling aloe vera or rose water instead of lemon juice.\",\"question\":\"Is turmeric paste safe for all acne?\"}]', '[\"Sushruta Samhita Nidana Sthana\",\"Sharangdhara Samhita\",\"American Academy of Dermatology Acne Guidelines\"]', 'Ayurveda Skin Specialist', '[\"pcos\"]', 'https://images.unsplash.com/photo-1629909613654-28e377c37b09?w=500&q=80', '[\"https://images.unsplash.com/photo-1629909613654-28e377c37b09?w=500&q=80\"]', '[]', '4.80', 510, 145, '2026-10-02 07:04:36', '2026-10-02 07:04:36'),
  ('dis-16', 'Hair Loss', 'hair-loss', 'Alopecia', '[\"Khalitya\"]', 'Skin Disorders', 'Trichological Imbalances', 'Premature shedding or thinning of hair, classified as Khalitya in Ayurveda, driven by Pitta heat.', 'In Ayurveda, hair loss is known as Khalitya. It occurs when aggravated Pitta dosha reaches the hair follicles, burning them and causing premature hair fall. High stress and blood impurities (Rakta-Pitta) accelerate this process.', '[\"Excessive intake of salty, spicy, and sour foods\",\"High mental stress and lack of sleep\",\"Use of chemical hair dyes and hard water\",\"Hormonal imbalances\"]', '[\"Gradual thinning of hair\",\"Excessive hair strands on comb or pillow\",\"Receding hairline\",\"Patchy hair loss\"]', '[\"Increased hair shedding during wash\",\"Itchy scalp\"]', '[\"Visible bald patches\",\"Significant scalp exposure\"]', '[\"Pitta-heavy body type\",\"Genetic history\",\"Nutritional deficiencies\",\"Stressful life\"]', '[\"Cosmetic stress\",\"Lowered self-confidence\"]', '[\"Use gentle herbal shampoos (Shikakai/Reetha)\",\"Avoid hot water head wash\",\"Massage scalp with cooling oils\"]', '[\"Apply fresh onion juice on scalp patches\",\"Rinse hair with cooled green tea or neem water\"]', 'Nasya therapy to nourish head channels, head massages (Shiro Abhyanga) with Bringraj oil, and blood purifying herbs.', 'Minoxidil topical solution, Finasteride oral medication, and hair transplant surgery.', '[\"Bhringraj (Eclipta alba)\",\"Amalaki (Amla)\",\"Brahmi\",\"Yashtimadhu\"]', '[\"Saptamrit Lauh\",\"Bhringrajasava\",\"Trichup Capsule\"]', '[\"Sesame seeds\",\"Coconut water\",\"Amla\",\"Leafy green vegetables\",\"Soaked almonds\"]', '[\"Sour pickles and citrus in excess\",\"Spicy food\",\"Refined white sugar\",\"Salty potato chips\"]', '[\"Adho Mukha Svanasana (Downward dog)\",\"Sarvangasana\",\"Balayam (Nail rubbing)\"]', '[\"Scalp massage exercises\",\"Regular cardio\"]', 'Gently comb hair with wooden comb, massage scalp with warm Bhringraj oil 