  `overview` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `benefits` json DEFAULT NULL,
  `procedure` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `duration` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `recoveryTime` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
