CREATE TABLE `clinic_stories` (
  `id` varchar(255) NOT NULL,
  `patientName` varchar(255) NOT NULL,
  `conditionName` varchar(255) NOT NULL,
  `clinicName` varchar(255) NOT NULL,
  `recoveryResult` varchar(255) NOT NULL,
  `quote` text NOT NULL,
  `avatar` varchar(500) DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

-- Baseline seed data for `clinic_stories` (3 rows)
INSERT INTO `clinic_stories` (`id`, `patientName`, `conditionName`, `clinicName`, `recoveryResult`, `quote`, `avatar`) VALUES
  ('c-story-1', 'Devendra Kulkarni', 'Chronic Spine Arthritis', 'Kerala Ayurveda Zen Sanctuary', 'Pain-Free Mobility Restored in 21 Days', 'The inpatient stay at the Zen Sanctuary was healing. The warm Abhyanga and Kativasti poolings cleared my chronic spine swelling completely.', 'https://images.unsplash.com/photo-1500648767791-00dcc994a43e?w=120&q=80'),
  ('c-story-2', 'Malini Hegde', 'Severe Metabolic Syndrome & Weight', 'Atreya Ayurvedic Hospital', 'Reversed Fatty Liver & Shed 12kg', 'Virechana purging followed by strict Samsarjana dietary rehabilitation at Atreya Pune hospital corrected my sluggish liver fire.', 'https://images.unsplash.com/photo-1494790108377-be9c29b29330?w=120&q=80'),
  ('c-story-3', 'Rajesh Malhotra', 'Cardiac Blockage & High BP', 'Madhavbaug Cardiac Care Clinic', 'Blood Pressure Regulated; Stent Avoided', 'Madhavbaug reversed my high blood pressure through non-invasive cardiac detox. The diet plans combined with breathing yoga work wonders.', 'https://images.unsplash.com/photo-1506794778202-cad84cf45f1d?w=120&q=80');

