-- Baseline seed data for `doctor_messages` (5 rows)
INSERT INTO `doctor_messages` (`id`, `doctorId`, `patientName`, `patientPhoto`, `sender`, `message`, `time`, `unread`, `createdAt`) VALUES
  ('msg-001', 'doc-dir-1', 'Priyanshi Sharma', 'https://images.unsplash.com/photo-1544005313-94ddf0286df2?w=60&q=80', 'patient', 'Doctor, my cycle has been more regular this month. Should I continue the Shatavari dose?', '10:15 AM', 0, '2026-10-02 13:17:28'),
  ('msg-002', 'doc-dir-1', 'Priyanshi Sharma', 'https://images.unsplash.com/photo-1544005313-94ddf0286df2?w=60&q=80', 'doctor', 'Wonderful progress! Yes, continue the Shatavari 500mg twice daily with warm milk. Add Ashoka churna 1 tsp at bedtime. See you on the scheduled session.', '10:28 AM', 0, '2026-10-02 13:17:28'),
  ('msg-003', 'doc-dir-1', 'Rahul Verma', 'https://images.unsplash.com/photo-1500648767791-00dcc994a43e?w=60&q=80', 'patient', 'The back pain has reduced significantly after the second Basti session. Thank you!', '09:30 AM', 1, '2026-10-02 13:17:28'),
  ('msg-004', 'doc-dir-1', 'Amit Joshi', 'https://images.unsplash.com/photo-1507003211169-0a1dd7228f2d?w=60&q=80', 'patient', 'Is it okay to do yoga in the morning before the Shirodhara session?', '07:00 AM', 0, '2026-10-02 13:17:28'),
  ('msg-005', 'doc-dir-1', 'Amit Joshi', 'https://images.unsplash.com/photo-1507003211169-0a1dd7228f2d?w=60&q=80', 'doctor', 'Gentle yoga is fine, but avoid intense inversions. Prefer Shavasana and Nadi Shodhana pranayama on therapy days.', '08:15 AM', 0, '2026-10-02 13:17:28');

