INSERT INTO `symptom_checker_data` (`id`, `category`, `data`, `createdAt`) VALUES
  ('symp-assessment_questions', 'ASSESSMENT_QUESTIONS', '[{\"id\":\"q1\",\"step\":1,\"type\":\"single\",\"options\":[{\"icon\":\"🫁\",\"label\":\"Digestive Issues\",\"value\":\"digestive\",\"description\":\"Bloating, acidity, constipation\"},{\"icon\":\"💨\",\"label\":\"Respiratory\",\"value\":\"respiratory\",\"description\":\"Cough, cold, breathing issues\"},{\"icon\":\"🧠\",\"label\":\"Mental Wellness\",\"value\":\"mental\",\"description\":\"Stress, anxiety, brain fog\"},{\"icon\":\"🦴\",\"label\":\"Pain & Inflammation\",\"value\":\"pain\",\"description\":\"Joint pain, headache, muscle ache\"},{\"icon\":\"✨\",\"label\":\"Skin Issues\",\"value\":\"skin\",\"description\":\"Rash, acne, dryness\"},{\"icon\":\"⚡\",\"label\":\"Energy & Vitality\",\"value\":\"energy\",\"description\":\"Fatigue, burnout, low motivation\"},{\"icon\":\"🌙\",\"label\":\"Sleep Problems\",\"value\":\"sleep\",\"description\":\"Insomnia, restless sleep\"},{\"icon\":\"🌿\",\"label\":\"General Wellness\",\"value\":\"general\",\"description\":\"Overall health optimization\"}],\"question\":\"What is your primary concern today?\",\"subtitle\":\"Select the area that best describes your main health issue\"},{\"id\":\"q2\",\"step\":2,\"type\":\"single\",\"options\":[{\"icon\":\"📅\",\"label\":\"Started Today\",\"value\":\"today\",\"description\":\"Less than 24 hours\"},{\"icon\":\"📆\",\"label\":\"1–7 Days\",\"value\":\"week\",\"description\":\"This past week\"},{\"icon\":\"🗓️\",\"label\":\"1–4 Weeks\",\"value\":\"month\",\"description\":\"This past month\"},{\"icon\":\"📊\",\"label\":\"1–6 Months\",\"value\":\"months\",\"description\":\"Several months\"},{\"icon\":\"🔄\",\"label\":\"More than 6 Months\",\"value\":\"chronic\",\"description\":\"Chronic condition\"}],\"question\":\"How long have you been experiencing these symptoms?\",\"subtitle\":\"Duration helps determine whether this is acute or chronic\"},{\"id\":\"q3\",\"max\":10,\"min\":1,\"step\":3,\"type\":\"scale\",\"question\":\"How would you rate your current energy level?\",\"subtitle\":\"Slide to indicate your overall vitality today\"},{\"id\":\"q4\",\"step\":4,\"type\":\"single\",\"options\":[{\"icon\":\"💨\",\"label\":\"Vata\",\"value\":\"vata\",\"description\":\"Thin build, creative, easily anxious\"},{\"icon\":\"🔥\",\"label\":\"Pitta\",\"value\":\"pitta\",\"description\":\"Medium build, focused, prone to anger\"},{\"icon\":\"🌊\",\"label\":\"Kapha\",\"value\":\"kapha\",\"description\":\"Heavy build, calm, slow metabolism\"},{\"icon\":\"⚡\",\"label\":\"Vata-Pitta\",\"value\":\"vata-pitta\",\"description\":\"Mix of air & fire energies\"},{\"icon\":\"🌿\",\"label\":\"Pitta-Kapha\",\"value\":\"pitta-kapha\",\"description\":\"Mix of fire & earth energies\"},{\"icon\":\"🌬️\",\"label\":\"Vata-Kapha\",\"value\":\"vata-kapha\",\"description\":\"Mix of air & water energies\"},{\"icon\":\"☯️\",\"label\":\"Tridoshic\",\"value\":\"tridosha\",\"description\":\"Balanced all three Doshas\"},{\"icon\":\"❓\",\"label\":\"Not Sure\",\"value\":\"unknown\",\"description\":\"Help me determine my Dosha\"}],\"question\":\"What is your body constitution (Prakriti)?\",\"subtitle\":\"Your dominant Dosha type according to Ayurveda\"},{\"id\":\"q5\",\"step\":5,\"type\":\"multi\",\"options\":[{\"icon\":\"💻\",\"label\":\"Sedentary Job\",\"value\":\"sedentary\"},{\"icon\":\"🍽️\",\"label\":\"Irregular Meal Times\",\"value\":\"irregular-meals\"},{\"icon\":\"🌙\",\"label\":\"Late Night Sleeping\",\"value\":\"late-nights\"},{\"icon\":\"😰\",\"label\":\"High Stress Work\",\"value\":\"high-stress\"},{\"icon\":\"🍔\",\"label\":\"Processed Food Diet\",\"value\":\"processed-food\"},{\"icon\":\"🚭\",\"label\":\"Alcohol/Smoking\",\"value\":\"alcohol\"},{\"icon\":\"🏋️\",\"label\":\"Regular Exercise\",\"value\":\"exercise\"},{\"icon\":\"🧘\",\"label\":\"Meditation Practice\",\"value\":\"meditation\"},{\"icon\":\"🌳\",\"label\":\"Outdoor Activities\",\"value\":\"outdoor\"}],\"question\":\"Which lifestyle factors apply to you?\",\"subtitle\":\"Select all that regularly affect your daily life\"},{\"id\":\"q6\",\"step\":6,\"type\":\"single\",\"options\":[{\"icon\":\"😌\",\"label\":\"Excellent (7–9 hrs, refreshing)\",\"value\":\"excellent\",\"description\":\"Wake up energized daily\"},{\"icon\":\"😊\",\"label\":\"Good (6–7 hrs, mostly restful)\",\"value\":\"good\",\"description\":\"Generally fine with minor issues\"},{\"icon\":\"😐\",\"label\":\"Fair (5–6 hrs, sometimes disturbed)\",\"value\":\"fair\",\"description\":\"Occasional issues\"},{\"icon\":\"😔\",\"label\":\"Poor (< 5 hrs, disturbed)\",\"value\":\"poor\",\"description\":\"Frequent sleep issues\"},{\"icon\":\"😩\",\"label\":\"Chronic Insomnia\",\"value\":\"insomnia\",\"description\":\"Severely impacted quality of life\"}],\"question\":\"How is your sleep quality on average?\",\"subtitle\":\"Select the option that best describes your sleep\"},{\"id\":\"q7\",\"step\":7,\"type\":\"single\",\"options\":[{\"icon\":\"🥗\",\"label\":\"Sattvic (Pure vegetarian)\",\"value\":\"sattvic\",\"description\":\"Fresh, balanced, whole foods\"},{\"icon\":\"🥦\",\"label\":\"Vegetarian\",\"value\":\"vegetarian\",\"description\":\"Plant-based with dairy\"},{\"icon\":\"🍗\",\"label\":\"Non-vegetarian\",\"value\":\"non-veg\",\"description\":\"Includes meat, fish, eggs\"},{\"icon\":\"🥘\",\"label\":\"Mixed Diet\",\"value\":\"mixed\",\"description\":\"Variety of all food types\"},{\"icon\":\"🌱\",\"label\":\"Vegan\",\"value\":\"vegan\",\"description\":\"Strictly plant-based\"}],\"question\":\"Describe your diet pattern\",\"subtitle\":\"What best describes your regular eating habits?\"},{\"id\":\"q8\",\"step\":8,\"type\":\"text\",\"question\":\"Any additional symptoms or concerns?\",\"subtitle\":\"Describe anything else you\'d like our AI to consider\",\"placeholder\":\"e.g., I also feel very cold in winters, my digestion gets worse after stress...\"}]', '2026-10-02 13:17:28'),
  ('symp-ayurvedic_remedies', 'AYURVEDIC_REMEDIES', '[{\"id\":\"r1\",\"icon\":\"🌿\",\"name\":\"Ashwagandha\",\"type\":\"herb\",\"dosage\":\"300–600mg extract daily\",\"rating\":4.9,\"timing\":\"Evening with warm milk\",\"urgency\":\"therapeutic\",\"benefits\":[\"Reduces cortisol\",\"Improves sleep quality\",\"Boosts immunity\",\"Enhances energy\"],\"forDoshas\":[\"Vata\"],\"description\":\"The powerful adaptogen for stress, anxiety and vitality restoration\"},{\"id\":\"r2\",\"icon\":\"🍯\",\"name\":\"Triphala\",\"type\":\"herb\",\"dosage\":\"1 tsp powder\",\"rating\":4.8,\"timing\":\"Bedtime with warm water\",\"urgency\":\"therapeutic\",\"benefits\":[\"Cleanses digestive tract\",\"Rich in antioxidants\",\"Regulates bowels\",\"Rejuvenates tissues\"],\"forDoshas\":[\"Vata\",\"Pitta\",\"Kapha\"],\"description\":\"The tridoshic powerhouse blend for digestive health and detoxification\"},{\"id\":\"r3\",\"icon\":\"🍵\",\"name\":\"Tulsi Tea\",\"type\":\"herb\",\"dosage\":\"2–3 fresh leaves or 1 tsp dried\",\"rating\":4.7,\"timing\":\"Morning on empty stomach\",\"urgency\":\"supportive\",\"benefits\":[\"Fights respiratory infections\",\"Anti-inflammatory\",\"Reduces stress\",\"Boosts immunity\"],\"forDoshas\":[\"Kapha\",\"Vata\"],\"description\":\"Holy Basil - the Queen of Herbs for respiratory health and immunity\"},{\"id\":\"r4\",\"icon\":\"💆\",\"name\":\"Abhyanga (Oil Massage)\",\"type\":\"therapy\",\"rating\":4.9,\"timing\":\"Morning before bath, 15–20 minutes\",\"urgency\":\"therapeutic\",\"benefits\":[\"Calms nervous system\",\"Improves circulation\",\"Nourishes skin\",\"Promotes deep sleep\"],\"forDoshas\":[\"Vata\"],\"description\":\"Traditional Ayurvedic warm oil self-massage for grounding and nourishment\"},{\"id\":\"r5\",\"icon\":\"🧠\",\"name\":\"Brahmi\",\"type\":\"herb\",\"dosage\":\"300mg extract\",\"rating\":4.8,\"timing\":\"Morning with ghee\",\"urgency\":\"therapeutic\",\"benefits\":[\"Enhances memory\",\"Reduces anxiety\",\"Supports focus\",\"Calms mind\"],\"forDoshas\":[\"Vata\",\"Pitta\"],\"description\":\"Medhya Rasayana - the supreme brain tonic for memory and mental clarity\"},{\"id\":\"r6\",\"icon\":\"🥗\",\"name\":\"Sattvic Diet\",\"type\":\"diet\",\"rating\":4.7,\"timing\":\"Daily meal practice\",\"urgency\":\"preventive\",\"benefits\":[\"Balances all doshas\",\"Calms mind\",\"Improves digestion\",\"Boosts prana\"],\"forDoshas\":[\"Vata\",\"Pitta\",\"Kapha\"],\"description\":\"Pure, life-force rich foods that promote clarity, peace and vitality\"},{\"id\":\"r7\",\"icon\":\"🧘\",\"name\":\"Pranayama\",\"type\":\"yoga\",\"dosage\":\"Nadi Shodhana, Bhramari, Kapalbhati\",\"rating\":4.9,\"timing\":\"20 minutes morning\",\"urgency\":\"therapeutic\",\"benefits\":[\"Oxygenates blood\",\"Calms nervous system\",\"Increases lung capacity\",\"Reduces anxiety\"],\"forDoshas\":[\"Vata\",\"Pitta\",\"Kapha\"],\"description\":\"Controlled breathing practices to balance prana and calm the mind\"},{\"id\":\"r8\",\"icon\":\"🫖\",\"name\":\"Ginger-Honey Tea\",\"type\":\"diet\",\"dosage\":\"1 inch ginger + 1 tsp honey\",\"rating\":4.6,\"timing\":\"Before meals\",\"urgency\":\"supportive\",\"benefits\":[\"Improves digestion\",\"Reduces nausea\",\"Anti-inflammatory\",\"Boosts metabolism\"],\"forDoshas\":[\"Kapha\",\"Vata\"],\"description\":\"Time-honored digestive remedy that kindles Agni (digestive fire)\"},{\"id\":\"r9\",\"icon\":\"🍈\",\"name\":\"Amalaki (Amla)\",\"type\":\"herb\",\"dosage\":\"1 fresh fruit or 1 tsp powder\",\"rating\":4.8,\"timing\":\"Morning empty stomach\",\"urgency\":\"preventive\",\"benefits\":[\"Extreme antioxidant action\",\"Cools Pitta fire\",\"Rejuvenates tissues\",\"Eye health\"],\"forDoshas\":[\"Pitta\"],\"description\":\"The divine fruit - richest natural source of Vitamin C and Pitta pacifier\"},{\"id\":\"r10\",\"icon\":\"🌙\",\"name\":\"Yoga Nidra\",\"type\":\"lifestyle\",\"rating\":4.9,\"timing\":\"30–45 minutes, mid-afternoon\",\"urgency\":\"therapeutic\",\"benefits\":[\"Equivalent to 4 hrs sleep\",\"Reduces stress hormones\",\"Heals nervous system\",\"Improves sleep quality\"],\"forDoshas\":[\"Vata\",\"Pitta\"],\"description\":\"Yogic sleep - a profound relaxation practice for deep rest and healing\"},{\"id\":\"r11\",\"icon\":\"🌶️\",\"name\":\"Trikatu\",\"type\":\"herb\",\"dosage\":\"250mg before meals\",\"rating\":4.6,\"timing\":\"Before meals with honey\",\"urgency\":\"therapeutic\",\"benefits\":[\"Speeds metabolism\",\"Burns fat\",\"Reduces congestion\",\"Improves digestion\"],\"forDoshas\":[\"Kapha\"],\"description\":\"Three spices blend (ginger, black pepper, pippali) to ignite Kapha metabolism\"},{\"id\":\"r12\",\"icon\":\"📅\",\"name\":\"Dinacharya Routine\",\"type\":\"lifestyle\",\"rating\":4.9,\"timing\":\"Follow consistently daily\",\"urgency\":\"preventive\",\"benefits\":[\"Synchronizes body rhythms\",\"Prevents disease\",\"Builds Ojas (vitality)\",\"Establishes balance\"],\"forDoshas\":[\"Vata\",\"Pitta\",\"Kapha\"],\"description\":\"Daily Ayurvedic routine - the single most powerful tool for long-term health\"}]', '2026-10-02 13:17:28'),
  ('symp-dosha_profiles', 'DOSHA_PROFILES', '[{\"diet\":[\"Warm soups\",\"Ghee\",\"Root vegetables\",\"Sweet fruits\",\"Nuts & seeds\"],\"color\":\"#7C3AED\",\"dosha\":\"Vata\",\"herbs\":[\"Ashwagandha\",\"Brahmi\",\"Triphala\",\"Shatavari\",\"Ginger\"],\"gradient\":\"from-purple-500 to-indigo-600\",\"lifestyle\":[\"Regular sleep schedule\",\"Gentle yoga\",\"Warm oil massage\",\"Avoid cold foods\",\"Meditation\"],\"percentage\":45,\"description\":\"Vata governs movement, creativity and nervous system. Imbalanced Vata causes anxiety, dryness and digestive irregularity.\",\"primaryTraits\":[\"Creative\",\"Quick-minded\",\"Adaptable\",\"Enthusiastic\",\"Sensitive\"],\"recommendations\":[\"Warm sesame oil massage (Abhyanga)\",\"Ashwagandha milk before bed\",\"Triphala for digestion\",\"Regular meal times\",\"Warm cooked foods\"],\"imbalanceSymptoms\":[\"Anxiety\",\"Dry skin\",\"Constipation\",\"Joint pain\",\"Insomnia\",\"Bloating\"]},{\"diet\":[\"Coconut water\",\"Sweet fruits\",\"Leafy greens\",\"Cucumber\",\"Dairy (cooling)\"],\"color\":\"#DC2626\",\"dosha\":\"Pitta\",\"herbs\":[\"Amalaki\",\"Shatavari\",\"Brahmi\",\"Neem\",\"Coriander\"],\"gradient\":\"from-red-500 to-orange-500\",\"lifestyle\":[\"Moonlight walks\",\"Swimming/cooling exercise\",\"Avoid midday sun\",\"Cooling pranayama\",\"Art/creativity\"],\"percentage\":30,\"description\":\"Pitta governs transformation, metabolism and intellect. Imbalanced Pitta causes inflammation, anger and skin issues.\",\"primaryTraits\":[\"Focused\",\"Ambitious\",\"Intelligent\",\"Organized\",\"Passionate\"],\"recommendations\":[\"Coconut oil application\",\"Shatavari churna\",\"Amalaki (Amla)\",\"Cooling foods\",\"Avoid spicy food\"],\"imbalanceSymptoms\":[\"Acid reflux\",\"Skin rashes\",\"Anger\",\"Inflammation\",\"Fever\",\"Migraines\"]},{\"diet\":[\"Light spicy foods\",\"Bitter vegetables\",\"Legumes\",\"Honey\",\"Warm ginger tea\"],\"color\":\"#059669\",\"dosha\":\"Kapha\",\"herbs\":[\"Trikatu\",\"Guggul\",\"Triphala\",\"Tulsi\",\"Punarnava\"],\"gradient\":\"from-emerald-500 to-teal-600\",\"lifestyle\":[\"Morning exercise\",\"Dry brushing\",\"Avoid daytime naps\",\"Stimulating activities\",\"Social interaction\"],\"percentage\":25,\"description\":\"Kapha governs structure, lubrication and immunity. Imbalanced Kapha causes weight gain, lethargy and respiratory issues.\",\"primaryTraits\":[\"Stable\",\"Compassionate\",\"Patient\",\"Loyal\",\"Strong\"],\"recommendations\":[\"Dry brushing (Garshana)\",\"Trikatu (3 peppers)\",\"Honey with warm water\",\"Morning exercise\",\"Fasting periodically\"],\"imbalanceSymptoms\":[\"Weight gain\",\"Congestion\",\"Lethargy\",\"Depression\",\"Excessive sleep\",\"Oily skin\"]}]', '2026-10-02 13:17:28'),
